// Model of jsonschema _utils.uniq + equal + CPython list.sort (n<64 path)
export const NAN = Symbol('nan'); // we tag values
// value model: {t:'null'|'bool'|'int'|'float'|'str'|'arr'|'obj', v}
export const TRUE_S = {t:'sent', v:true}, FALSE_S = {t:'sent', v:false};
function unbool(x){ if(x.t==='bool') return x.v?TRUE_S:FALSE_S; return x; }
class PyTypeError extends Error {}
function isNum(x){return x.t==='int'||x.t==='float';}
function numLt(a,b){ // exact compare (use BigInt for int)
  if(a.t==='float'&&Number.isNaN(a.v)) return false;
  if(b.t==='float'&&Number.isNaN(b.v)) return false;
  if(a.t==='int'&&b.t==='int') return a.v<b.v;
  if(a.t==='int'&&b.t==='float'){ if(!Number.isFinite(b.v)) return b.v>0; return cmpIntFloat(a.v,b.v)<0; }
  if(a.t==='float'&&b.t==='int'){ if(!Number.isFinite(a.v)) return a.v<0; return -cmpIntFloat(b.v,a.v)<0; }
  return a.v<b.v;
}
function cmpIntFloat(i,f){ // i BigInt, f finite number -> -1/0/1
  const fr = ratOfFloat(f); // {n:BigInt,d:BigInt}
  const l = i*fr.d, r = fr.n; return l<r?-1:l>r?1:0;
}
function ratOfFloat(f){ let d=1n,x=f; while(!Number.isInteger(x)){x*=2;d*=2n;} return {n:BigInt(x),d}; }
function numEq(a,b){
  if(a.t==='float'&&Number.isNaN(a.v)) return false;
  if(b.t==='float'&&Number.isNaN(b.v)) return false;
  if(a.t==='int'&&b.t==='int') return a.v===b.v;
  if(a.t==='int'&&b.t==='float'){ if(!Number.isFinite(b.v)) return false; return cmpIntFloat(a.v,b.v)===0; }
  if(a.t==='float'&&b.t==='int'){ if(!Number.isFinite(a.v)) return false; return cmpIntFloat(b.v,a.v)===0; }
  return a.v===b.v;
}
// PyObject_RichCompareBool(EQ) with identity shortcut
function pyEqB(a,b){ if(a===b) return true; return pyEq(a,b); }
function pyEq(a,b){
  if(isNum(a)&&isNum(b)) return numEq(a,b);
  if(a.t==='sent'||b.t==='sent') return a===b;
  if(a.t==='null'||b.t==='null') return a.t===b.t;
  if(a.t==='str'&&b.t==='str') return a.v===b.v;
  if(a.t==='arr'&&b.t==='arr'){ if(a.v.length!==b.v.length) return false; for(let i=0;i<a.v.length;i++) if(!pyEqB(a.v[i],b.v[i])) return false; return true; }
  if(a.t==='obj'&&b.t==='obj'){ const ka=[...a.v.keys()],kb=[...b.v.keys()]; if(ka.length!==kb.length) return false; for(const k of ka){ if(!b.v.has(k)) return false; if(!pyEqB(a.v.get(k),b.v.get(k))) return false; } return true; }
  return false; // different types -> not equal (no TypeError for ==)
}
function pyLt(a,b){
  if(a===b && a.t!=='float') { /* still goes through __lt__ */ }
  if(isNum(a)&&isNum(b)) return numLt(a,b);
  if(a.t==='str'&&b.t==='str') return a.v<b.v; // code-point order (JS < on strings is UTF-16 code unit... approximate)
  if(a.t==='arr'&&b.t==='arr'){
    const n=Math.min(a.v.length,b.v.length);
    for(let i=0;i<n;i++){ if(!pyEqB(a.v[i],b.v[i])) return pyLt(a.v[i],b.v[i]); }
    return a.v.length<b.v.length;
  }
  throw new PyTypeError('unorderable '+a.t+' < '+b.t);
}
// jsonschema _utils.equal
export function equal(a,b){
  if(a===b) return true;
  if(a.t==='str'||b.t==='str') return pyEq(a,b);
  if((a.t==='str'||a.t==='arr')&&(b.t==='str'||b.t==='arr')) return seqEq(a,b);
  if(a.t==='arr'&&b.t==='arr') return seqEq(a,b);
  if(a.t==='obj'&&b.t==='obj') return mapEq(a,b);
  return pyEq(unbool(a),unbool(b));
}
function seqEq(a,b){ if(a.v.length!==b.v.length) return false; for(let i=0;i<a.v.length;i++) if(!equal(a.v[i],b.v[i])) return false; return true; }
function mapEq(a,b){ if(a.v.size!==b.v.size) return false; for(const k of a.v.keys()){ if(!b.v.has(k)) return false; if(!equal(a.v.get(k),b.v.get(k))) return false; } return true; }
// CPython list.sort for n < 64
export function pySort(arr){
  const a=arr.slice(); const n=a.length; if(n<2) return a;
  if(n>=64) throw new Error('model only n<64');
  // count_run
  let p=1, descending=false;
  if(pyLt(a[1],a[0])){ descending=true; for(p=2;p<n;p++){ if(!pyLt(a[p],a[p-1])) break; } }
  else { for(p=2;p<n;p++){ if(pyLt(a[p],a[p-1])) break; } }
  let run=p;
  if(descending){ const s=a.slice(0,run).reverse(); for(let i=0;i<run;i++) a[i]=s[i]; }
  // binarysort a[run:n] into a[0:run]
  for(let start=run;start<n;start++){
    const pivot=a[start]; let l=0,r=start;
    while(l<r){ const m=l+((r-l)>>1); if(pyLt(pivot,a[m])) r=m; else l=m+1; }
    for(let i=start;i>l;i--) a[i]=a[i-1];
    a[l]=pivot;
  }
  return a;
}
export function uniq(container){
  const u=container.map(unbool);
  try{
    const s=pySort(u);
    for(let i=0;i+1<s.length;i++) if(equal(s[i],s[i+1])) return false;
    return true;
  }catch(e){
    if(!(e instanceof PyTypeError)) throw e;
    const seen=[];
    for(const e0 of u){ if(seen.some(s=>equal(e0,s))) return false; seen.push(e0); }
    return true;
  }
}
