const INF={t:'float',v:Infinity}, NINF={t:'float',v:-Infinity};
const I=n=>({t:'int',v:BigInt(n)}), FL=n=>({t:'float',v:n}), S=s=>({t:'str',v:s});
const A=(...xs)=>({t:'arr',v:xs}), O=(pairs)=>({t:'obj',v:new Map(pairs)});
